#!/usr/bin/env python3
"""Jarvis V8: GitHub/Codespaces üzerinden tek dosyalık güncelleme.
Ağdan kod indirmez; aşağıdaki gömülü yamayı uygular.
.env, kişisel hafıza ve veri klasörlerini değiştirmez.
"""
import base64
import datetime
import gzip
import hashlib
import json
from pathlib import Path
import subprocess
import sys

MANIFEST = json.loads("{\".env.example\": \"111ff6522a64c8d19dbfcd674fcd7b51a37ecd330a209e10c8c12bf822258048\", \".github/workflows/checks.yml\": \"1086cbffeb80663ca809fce67d05155e303ac18d57811ec23bc04c02f1743159\", \"README.md\": \"9d61021047814b6dc23cd0a0872be1d146305243656f9783a468127a5c40da14\", \"docs-v8.md\": \"b0cbc9cf6cb5c99e51ffb48c999c1dd9008d974037149dbe999e177f215f0923\", \"lib/agents/orchestrator.js\": \"a4fd825f2bb07161f1c334cb69a1ad35b3dae82fbba63fa047be2c2a48cbe1dc\", \"lib/agents/providers.js\": \"927d03d07bea388a40046058eed1ef04a7584ab73a31ab906610a37fe0f0c103\", \"lib/clock.js\": \"8fbfec7b26ab70d5cb6b774ee0e207d72633b1f0fdc88c99e231773599c81696\", \"lib/dashboard.js\": \"ff5811d92c5ea14e5981e8ed6513bb55e9418301854e7e72d17cf3eddc3f4179\", \"lib/events.js\": \"904ecb824278931d90290e68ed020ec48980ff290727bda583d990c35fee0a7b\", \"lib/home.js\": \"8ca92c3c3ae3cd5dff288b17e6e941bc1fe0b076f21c4f38db34f8f79f91a1d4\", \"lib/jobs.js\": \"53a26fee55b270a189276975e53b8b87cc65d83cac2e879bc7c083833e214dce\", \"lib/live/config.js\": \"dcc6bfd7b84f233cfcde6f07fe947664dde4ac4e4d2bda190bf9c7d502085b43\", \"lib/live/service.js\": \"8181bd428d9bc10d3d82cbfbbcb45f098eaa32f12b361c8a3d120b2712c0fe5d\", \"lib/memory.js\": \"66caddf925c54970bdb0d588f2355361a8c5c1b5b9fae3353bbd081e04b9e05c\", \"lib/runtime.js\": \"1e1661a71128b1556ee607b72a6212b086a0a287bdedc1a6beabbb763e6d2e8a\", \"lib/settings.js\": \"05e7c19e3e6fc3623d975a06b70ab23127b2e1bcac77416201d564a4b366f11b\", \"package.json\": \"fc5f47b88529b33cad941a54a03841578762a97deedb58c1bf40e534d5f159c9\", \"public/jarvis-pcm-worklet.js\": \"3aef943db6e2d8547d9deae425b5fead40b147640f4e9fe2e33464455c1745b9\", \"server.js\": \"730e25b45a347c9e098c2ef953c445473060d7d4b988adfe351076b4579bcd6a\", \"src/App.jsx\": \"9738a1074e87abb32bb8cf2728e24c73cd4ac1a812545dd1580f786f682609fc\", \"src/ChatPanel.jsx\": \"fd5a10640d215d391c0eaedb2fa9e36129bbb24eb53554a64fbbeccfb5d74150\", \"src/components/Dashboard.jsx\": \"e6044e658d8773b84942880947318830bfa3583ced5403caec9723acdc85fd8c\", \"src/components/HomePanel.jsx\": \"27293f20b2f2a8f78a1ec5de75bac0fec9c910c5cec9b5cafc562e015298f112\", \"src/components/PhotoInput.jsx\": \"9885c2a1c524c95121b8bc49fb127dae3734b61a941aa7fd119781d4aa13a522\", \"src/components/VoiceOrb.jsx\": \"f0846525d47158fee5722b539dd00e1a28bcc2350eea3325e1a04a9f1d4c781d\", \"src/core/api.js\": \"6e6d760e9006983e7d8ca233bad952b82b16639d1d5c6ba7071389fd455097c7\", \"src/core/appActions.js\": \"3151115ba30684bde88c3c59e7f47d4f9e082fb5a64a1ba3cdba078d24f553ad\", \"src/core/memory.js\": \"d330663ae8b551dd0875cf73cfdac21f7222371569f7a24ce064f93deda2a3fb\", \"src/core/voice.js\": \"f124cd772a0a1a1df37f477a2a29e6adabd9ff0842c4a96fedd0135335312a2a\", \"src/hooks/useLiveVoice.js\": \"480ae95120071321fa5b554195f8a778f3547a388e5f7602cc370f7f52ad278c\", \"src/hooks/usePerformance.js\": \"cf3577490df4a81fcb6d54fa6704ea3723642a4cabd4d7b9a2505af5a1687f1c\", \"src/hooks/useSession.js\": \"e7b15b6f0de583df80beaf9e82cab37a05a8bd7690ee91d20ac3572fae036375\", \"src/live/audio.js\": \"1c1913c4fbfdac4d0d1d0b97ab11a98afaf4977ea83d8f57ca2b598d29154b8c\", \"src/live/controller.js\": \"ac357ab180c6d1ab814c2efc0e374769c6cc3ae60dae9e94c783c16dbd8d859f\", \"src/styles/upgrade.css\": \"ba382f99c8e1e5e93ba0acbecfcbc1b7c3e49e795a3dbce9b7204f2b2409d000\", \"src/styles/voice.css\": \"69b36e0bf97ba1b0e39d426223dc162cb2fe69941f4f9c73e5549294387c5c2c\", \"test/integration.test.js\": \"889e6ad55886bba5d72e503dc977fda3bc575e90e1dca04d7a66ac7a68f6a3a1\", \"test/live.test.js\": \"5828e3bfe83935e4164ecd5b54cb79e8062d20e646c2ffe59de73a39c4d6c453\", \"test/upgrade.test.js\": \"a809e95aea6e870781e03062c4d340be76620bcc8beeaf0c61f6200929278a5d\"}")
PAYLOADS = json.loads("{\"tam\": \"\", \"v7_uzerine\": \"\"}")

def git(*args, input=None, check=True):
    return subprocess.run(['git', *args], cwd=root, input=input, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=check)

def stop(message):
    print('\nDURDURULDU: ' + message, file=sys.stderr)
    sys.exit(1)

root = Path(__file__).resolve().parent
try:
    top = Path(git('rev-parse', '--show-toplevel').stdout.decode().strip()).resolve()
except (subprocess.CalledProcessError, FileNotFoundError):
    stop('Dosyayı Jarvis Git deposunun ana klasörüne yükleyip Codespaces terminalinden çalıştırın.')
if top != root:
    stop('Güncelleme dosyası deponun ana klasöründe olmalı.')

for name in MANIFEST:
    relative = Path(name)
    if relative.is_absolute() or '..' in relative.parts or relative.parts[0] in {'.git', 'data'} or name == '.env':
        stop('Geçersiz güncelleme yolu.')

if all((root/name).is_file() and hashlib.sha256((root/name).read_bytes()).hexdigest() == digest for name,digest in MANIFEST.items()):
    print('V8 dosyaları zaten güncel. Güncelleme tekrar uygulanmadı.')
    sys.exit(0)

if git('status', '--porcelain', '--untracked-files=no').stdout.strip():
    stop('Kaydedilmemiş kod değişiklikleri var. Dosyalarınız korunması için işlem yapılmadı. Terminal çıktısını paylaşın; reset veya clean kullanmayın.')

chosen = None
for label, encoded in PAYLOADS.items():
    patch = gzip.decompress(base64.b64decode(encoded))
    result = git('apply', '--check', '--whitespace=nowarn', '-', input=patch, check=False)
    if result.returncode == 0:
        chosen = (label, patch)
        break
if chosen is None:
    stop('Mevcut kod beklenen V7/ana sürümle uyuşmuyor. Hiçbir proje dosyası değiştirilmedi. Terminal çıktısını paylaşın.')

stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
backup = 'backup/jarvis-before-v8-' + stamp
branch = 'jarvis-v8-test-' + stamp
try:
    git('branch', backup)
    git('switch', '-c', branch)
    git('apply', '--whitespace=nowarn', '-', input=chosen[1])
except subprocess.CalledProcessError as error:
    stop('Git işlemi tamamlanamadı. Çalışan dal ve değişiklikleri kontrol edin.\n' + error.stderr.decode(errors='replace'))

if not all((root/name).is_file() and hashlib.sha256((root/name).read_bytes()).hexdigest() == digest for name,digest in MANIFEST.items()):
    stop('Güncelleme sonrası dosya doğrulaması başarısız. Yedek dal: ' + backup)

print('\nV8 dosyaları başarıyla güncellendi ve dosya bütünlükleri doğrulandı.')
print('Çalışma dalı: ' + branch)
print('Önceki sürümün yedek dalı: ' + backup)
print('.env ve kişisel veri dosyalarınız değiştirilmedi.')
print('Bu sonuç uygulamanın çalıştığını değil, kodun doğru uygulandığını doğrular.')
print('Sıradaki adımlar: npm ci, npm test, npm run build, npm run jarvis')
print('Değişiklikler henüz commit veya push edilmedi. Önce test sonuçlarını kontrol edin.')
